{
  "name": "@graviton711/orchestra",
  "version": "0.9.8",
  "description": "OpenCode bundle: always-on senior-dev protocol, skills, 3-agent council, and verifiable long-horizon missions.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "skills",
    "agent-skills",
    "ai-agents",
    "llm",
    "long-horizon",
    "autonomous-agent",
    "developer-tools"
  ],
  "license": "MIT",
  "author": {
    "name": "graviton711",
    "url": "https://github.com/graviton711"
  },
  "homepage": "https://github.com/graviton711/orchestra#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/graviton711/orchestra.git"
  },
  "bugs": {
    "url": "https://github.com/graviton711/orchestra/issues"
  },
  "type": "module",
  "main": "./plugin/orchestra.mjs",
  "bin": {
    "orchestra-mission": "scripts/run-mission.mjs"
  },
  "exports": {
    ".": "./plugin/orchestra.mjs",
    "./skills/*": "./skills/*"
  },
  "files": [
    ".opencode/",
    "agents/",
    "core/",
    "plugin/",
    "rules/",
    "scripts/",
    "skills/",
    "LICENSE",
    "NOTICE.md",
    "mcp_config.json",
    "plugin.json"
  ],
  "scripts": {
    "postinstall": "node scripts/install-agents.mjs",
    "test": "node --test tests/*.test.js",
    "docs:check": "node scripts/check-docs.mjs",
    "notice": "node scripts/update-notice.mjs"
  },
  "engines": {
    "node": ">=20"
  },
  "publishConfig": {
    "access": "public"
  }
}
